function validate([grid]) {
  if (!Array.isArray(grid)) return 'grid must be a square matrix.';
  const n = grid.length;
  if (n < 3 || n > 49) return 'grid needs 3 to 49 rows.';
  if (n % 2 === 0) return 'n must be odd.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'grid must be square (n x n).';
    if (row.some(v => v !== 0 && v !== 1 && v !== 2)) return 'Every cell is 0, 1 or 2.';
  }
  return null;
}

