function minimumOperationsToWriteY(grid) {
  const n = grid.length;
  const center = Math.floor(n / 2);
  const inY = [0, 0, 0];
  const outY = [0, 0, 0];
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      const onArm = r <= center && (c === r || c === n - 1 - r);
      const onStem = r >= center && c === center;
      if (onArm || onStem) {
        inY[grid[r][c]]++;
      } else {
        outY[grid[r][c]]++;
      }
    }
  }
  const sizeY = inY[0] + inY[1] + inY[2];
  const sizeOut = n * n - sizeY;
  let best = Infinity;
  for (let yValue = 0; yValue < 3; yValue++) {
    for (let outValue = 0; outValue < 3; outValue++) {
      if (yValue === outValue) {
        continue;
      }
      const cost = (sizeY - inY[yValue]) + (sizeOut - outY[outValue]);
      best = Math.min(best, cost);
    }
  }
  return best;
}

