  const n = grid.length;
  const mid = (n - 1) / 2;
  const isY = grid.map(row => row.map(() => false));
  for (let step = 0; step <= mid; step++) {
    isY[step][step] = true;
    isY[step][n - 1 - step] = true;
  }
  for (let r = mid; r < n; r++) isY[r][mid] = true;
  let best = Infinity;
  for (const a of [0, 1, 2]) {
    for (const b of [0, 1, 2]) {
      if (a === b) continue;
      let changes = 0;
      for (let r = 0; r < n; r++)
        for (let c = 0; c < n; c++)
          if (grid[r][c] !== (isY[r][c] ? a : b)) changes++;
      best = Math.min(best, changes);
    }
  }
  return best;
}

