function generate(rand, size) {
  const n = size === 'large' ? 41 + 2 * Math.floor(rand() * 5) : 3 + 2 * Math.floor(rand() * 3);
  const mid = (n - 1) / 2;
  // Start from a clean Y in two random distinct values, then add noise so answers vary.
  const yValue = Math.floor(rand() * 3);
  const outValue = (yValue + 1 + Math.floor(rand() * 2)) % 3;
  const noise = rand();
  const grid = [];
  for (let r = 0; r < n; r++) {
    const row = [];
    for (let c = 0; c < n; c++) {
      const inside = (r <= mid && (c === r || c === n - 1 - r)) || (r >= mid && c === mid);
      row.push(rand() < noise ? Math.floor(rand() * 3) : (inside ? yValue : outValue));
    }
    grid.push(row);
  }
  return [grid];
}
